#!/usr/bin/env python3
"""Summarize document.xml paragraphs: style + text."""
import sys
from pathlib import Path
from xml.dom import minidom

path = Path(sys.argv[1]) if len(sys.argv) > 1 else Path("quarterly_report_unpacked/word/document.xml")
dom = minidom.parse(str(path))

ns = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"

def local(tag):
    return tag.split("}")[-1] if "}" in tag else tag

def get_text(elem):
    parts = []
    for node in elem.getElementsByTagName("w:t"):
        if node.firstChild:
            parts.append(node.firstChild.data)
    for node in elem.getElementsByTagName("w:delText"):
        if node.firstChild:
            parts.append("[del:" + node.firstChild.data + "]")
    return "".join(parts)

for i, p in enumerate(dom.getElementsByTagName("w:p")):
