    if pprs:
        styles = pprs[0].getElementsByTagName("w:pStyle")
        if styles:
            style = styles[0].getAttribute("w:val")
    text = get_text(p)
    runs = len(p.getElementsByTagName("w:r"))
    print(f"[{i}] style={style!r} runs={runs} text={text[:120]!r}")

