#!/usr/bin/env python3
"""Underline all headlines (all-caps section titles) in the quarterly report."""
import sys

sys.path.insert(0, '.codex/skills/docx')
from scripts.document import Document

W = 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'

# Schema order for CT_RPr children (indices for insertion before later elements)
RPR_ORDER = ['rStyle', 'rFonts', 'b', 'bCs', 'i', 'iCs', 'caps', 'smallCaps',
             'strike', 'dstrike', 'outline', 'shadow', 'emboss', 'imprint',
             'noProof', 'snapToGrid', 'vanish', 'webHidden', 'color', 'spacing',
             'w', 'kern', 'position', 'sz', 'szCs', 'highlight', 'u', 'effect',
             'bdr', 'shd', 'fitText', 'vertAlign', 'rtl', 'cs', 'em', 'lang',
             'eastAsianLayout', 'specVanish', 'oMath']

def para_text(p):
    parts = []
    for t in p.getElementsByTagNameNS(W, 't'):
        if t.firstChild:
            parts.append(t.firstChild.nodeValue)
    return ''.join(parts)

def local_name(node):
    return node.localName or node.tagName.split('}')[-1]

def insert_u(rpr, doc):
    """Insert <w:u w:val="single"/> into rPr in schema-correct position."""
    existing = None
    for child in rpr.childNodes:
        if child.nodeType == child.ELEMENT_NODE and local_name(child) == 'u':
            existing = child
            break
    if existing is not None:
        return False
    u_el = doc.createElementNS(W, 'w:u')
    u_el.setAttributeNS(W, 'w:val', 'single')
    # Find insertion point: after szCs/sz, before later elements
    order_idx = RPR_ORDER.index('u')
    insert_pos = None
    for child in rpr.childNodes:
        if child.nodeType == child.ELEMENT_NODE:
            name = local_name(child)
            if name in RPR_ORDER and RPR_ORDER.index(name) > order_idx:
                insert_pos = child
                break
    if insert_pos is not None:
        rpr.insertBefore(u_el, insert_pos)
    else:
        rpr.appendChild(u_el)
    return True

def main(unpacked):
    doc = Document(unpacked)
    editor = doc['word/document.xml']
    dom = editor.dom
    changed = []
    for p in dom.getElementsByTagNameNS(W, 'p'):
        text = para_text(p).strip()
        if not text or len(text) < 4:
            continue
        letters = [c for c in text if c.isalpha()]
        if not letters:
            continue
        # Headline: all-caps text, no sentence content (e.g., no digits-only lines)
        if text != text.upper():
            continue
        # Exclude table header rows / lines of dashes (already all-caps punctuation-only handled above)
        runs = [r for r in p.childNodes
                if r.nodeType == r.ELEMENT_NODE and local_name(r) == 'r']
        if not runs:
            continue
        for r in runs:
            rpr = None
            for child in r.childNodes:
                if child.nodeType == child.ELEMENT_NODE and local_name(child) == 'rPr':
                    rpr = child
                    break
            if rpr is None:
                rpr = dom.createElementNS(W, 'w:rPr')
                r.insertBefore(rpr, r.firstChild)
            if insert_u(rpr, dom):
                changed.append(text)
    if not changed:
        print('NO HEADLINES MODIFIED')
        sys.exit(1)
    doc.save()
    print('Underlined headlines:')
    for c in dict.fromkeys(changed):
        print(' -', c)

if __name__ == '__main__':
    main(sys.argv[1])

